"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["70758"],{10738(e){e.exports=JSON.parse('{"id":"F457","slug":"infrastructure-dscr-llcr","name":"Infrastructure Project: DSCR and Loan Life Cover","subject":"Alternative Investments","section":"Alternatives","topic":"Infrastructure investing","level":"Intermediate","aliases":["infrastructure investing","project finance cover ratios","LLCR","DSCR lock-up","CFADS"],"formula":{"latex":"DSCR_{t}=\\\\frac{CFADS_{t}}{DS_{t}},\\\\quad LLCR=\\\\frac{\\\\sum_{t}CFADS_{t}/(1+r)^{t}}{\\\\text{Debt}}","also":[],"text":"Cash flow available for debt service (CFADS) = operating cash flow after tax and capex; DSCR in year t = CFADS / (interest + principal due); LLCR = present value of CFADS over the loan life at the loan rate / debt outstanding; A project typically needs a minimum DSCR near 1.2 to 1.4 for stable assets, and pays no dividends below a lock-up level"},"symbols":[{"symbol":"CFADS_t","meaning":"Cash flow available to pay lenders in year t","unit":"money"},{"symbol":"DS_t","meaning":"Debt service (interest plus principal) due in year t","unit":"money"},{"symbol":"r","meaning":"Interest rate on the loan, used to discount","unit":"percent"}],"when_to_use":"Use it to test whether an infrastructure project (a toll road, solar farm, pipeline) can carry its debt. Lenders look at the cheapest year (minimum DSCR) and at the whole loan life (LLCR). A margin above 1 means income covers payments even if revenue falls short; a cover below 1 means equity must top up or lenders take a loss.","worked_example":{"problem":"A project expects CFADS of 120, 125, 130, 135, 140 and 145 over 6 years against debt service of 90 a year. The loan rate is 6%.","inputs":{"cf":[120,125,130,135,140,145],"ds":[90,90,90,90,90,90],"r":6},"steps":[{"label":"DSCR per year","working":null,"value":"1.33, 1.39, 1.44, 1.50, 1.56, 1.61"},{"label":"Minimum DSCR","working":"min([1.33333, 1.38889, 1.44444, 1.5, 1.55556, 1.61111])","value":"1.33"},{"label":"Average DSCR","working":null,"value":"1.47"},{"label":"Debt (present value of debt service at the loan rate)","working":null,"value":"442.56"},{"label":"LLCR = PV of CFADS / debt","working":null,"value":"1.46"},{"label":"Minimum DSCR if CFADS falls 20%","working":"1.33333 x 0.8","value":"1.07"},{"label":"Still at least 1.0? (1 = yes)","working":"1 if 1.06667>=1 else 0","value":"1"}],"answer":"The yearly DSCRs are 1.33, 1.39, 1.44, 1.50, 1.56, 1.61. The lowest is 1.33, the average is 1.47. Debt is worth 442.56 at 6% and the LLCR is 1.46. A cut of 20% in CFADS gives a minimum DSCR of 1.07, which is 1 (1 = still at least 1.0)."},"calculator":{"available":true,"inputs":[{"id":"cf","label":"CFADS per year","unit":"money","type":"list","default":[120,125,130,135,140,145],"hint":""},{"id":"ds","label":"Debt service per year","unit":"money","type":"list","default":[90,90,90,90,90,90],"hint":""},{"id":"r","label":"Loan interest rate","unit":"%","type":"number","default":6,"hint":""}],"checks":[{"expr":"count(cf)==count(ds)","message":"CFADS and debt service need the same number of years."}],"steps":[{"id":"dscr","label":"DSCR per year","expr":"divide(cf, ds)","format":"list2"},{"id":"mn","label":"Minimum DSCR","expr":"min(dscr)","format":"num2"},{"id":"av","label":"Average DSCR","expr":"mean(dscr)","format":"num2"},{"id":"debt","label":"Debt (present value of debt service at the loan rate)","expr":"sum(pvflows(r, ds))","format":"money"},{"id":"llcr","label":"LLCR = PV of CFADS / debt","expr":"sum(pvflows(r, cf))/debt","format":"num2"},{"id":"stress","label":"Minimum DSCR if CFADS falls 20%","expr":"mn*0.8","format":"num2"},{"id":"ok_","label":"Still at least 1.0? (1 = yes)","expr":"1 if stress>=1 else 0","format":"num0"}],"results":["mn","av","llcr","stress"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"mn":1.3333333333333333,"av":1.4722222222222223,"debt":442.5591893404851,"llcr":1.4628002121765067,"stress":1.0666666666666667,"ok_":1}},"finder":{"finds":"Whether project cash flows cover the debt","needs":"CFADS and debt service by year, loan rate"},"related":[{"slug":"cap-rate-valuation","name":"Net Operating Income and Cap-Rate Valuation"},{"slug":"npv","name":"Net Present Value (NPV)"}],"related_ids":["F450","F028"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>D</mi><mi>S</mi><mi>C</mi><msub><mi>R</mi><mi>t</mi></msub><mo>=</mo><mfrac><mrow><mi>C</mi><mi>F</mi><mi>A</mi><mi>D</mi><msub><mi>S</mi><mi>t</mi></msub></mrow><mrow><mi>D</mi><msub><mi>S</mi><mi>t</mi></msub></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>L</mi><mi>L</mi><mi>C</mi><mi>R</mi><mo>=</mo><mfrac><mrow><munder><mo>\u2211</mo><mi>t</mi></munder><mi>C</mi><mi>F</mi><mi>A</mi><mi>D</mi><msub><mi>S</mi><mi>t</mi></msub><mi mathvariant=\\"normal\\">/</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><msup><mo stretchy=\\"false\\">)</mo><mi>t</mi></msup></mrow><mtext>Debt</mtext></mfrac></mrow><annotation encoding=\\"application/x-tex\\">DSCR_{t}=\\\\frac{CFADS_{t}}{DS_{t}},\\\\quad LLCR=\\\\frac{\\\\sum_{t}CFADS_{t}/(1+r)^{t}}{\\\\text{Debt}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"information-ratio","name":"Information Ratio and Tracking Error"},"next":{"slug":"insider-trading-disgorgement","name":"Insider Trading: Profit Gained and Maximum Civil Penalty"},"lesson":null,"total":522}')}}]);